uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// --- ASSETS ---
uniform sampler2D iChannel0; 

// --- STANDARD CONTROLS ---
uniform float u_speed;
uniform float u_camera_dist; 
uniform float u_fov;
uniform float u_glow_intensity;

// --- VISUAL CONTROLS ---
uniform float u_turbulence_strength;
uniform float u_cloud_height; 
uniform float u_color_shift;
uniform float u_density_factor;
uniform float u_saturation;

out vec4 fragColor;

// --- LUMINA MATH LIB ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec3 rd = normalize(vec3(uv, -1.0 / max(0.1, u_fov))); 

    float t = iTime * ((u_speed <= 0.0) ? 0.2 : u_speed);

    // Accumulation
    vec4 col = vec4(0.0);

    // Start distance influenced by zoom fader
    float d = 0.1 + u_camera_dist; 

    for(int i = 0; i < 90; i++) {
        vec3 p = d * rd;

        // --- MULTI-THREAD TURBULENCE ---
        // Higher octaves and frequency shifting create many "gradient lines"
        float scale = 1.8; 
        vec3 p_orig = p;
        for(int j = 0; j < 6; j++) {
            p.xy *= rot(t * 0.04 + float(j) * 0.2);
            // Swizzling with an added offset creates the "parallel string" look
            p += u_turbulence_strength * sin(p.yzx * scale + float(j) * 1.5 - t) / scale;
            scale *= 1.4;
        }

        // --- STRING SEPARATION LOGIC ---
        // We use a periodic sine function on the Y-axis to create many parallel ribbons
        // This prevents it from looking like a single worm when zoomed out.
        float ribbonGrid = sin(p.y * 8.0 + p.z * 2.0);
        float strands = u_cloud_height - abs(ribbonGrid); 

        // Volumetric Step Size
        float stepSize = 0.015 + max(strands, -strands * 0.2) * 0.4;
        d += stepSize;

        // --- LUSH PIGMENT ---
        float hue = fract(u_color_shift + p_orig.x * 0.08 + t * 0.02);
        vec3 pigment = hsv2rgb(vec3(hue, clamp(u_saturation, 0.4, 1.0), 1.0));

        // Fire Palette from Getty Image Style
        vec3 fireCol = mix(vec3(0.02, 0.0, 0.0), pigment, smoothstep(-0.3, 0.5, strands));

        // Density Logic: Lower divisor = sharper, more numerous lines
        float glow = exp(strands / (0.4 / max(0.1, abs(u_density_factor))));

        // Accumulate with additive glow and opacity
        col.rgb += fireCol * glow * (u_glow_intensity * 0.012);
        col.a += glow * 0.08;

        if (col.a > 0.995) break;
    }

    // --- FINAL 4K GRADE ---
    vec3 finalCol = col.rgb;

    // Exposure compression to prevent white-out
    finalCol = finalCol / (1.0 + finalCol * 0.25); 

    // High contrast and color depth
    finalCol = pow(finalCol, vec3(1.3, 1.2, 1.1));

    // Vignette
    finalCol *= smoothstep(1.6, 0.4, length(uv));

    fragColor = vec4(clamp(finalCol, 0.0, 1.0), 1.0);
}
